    const w = slot.clientWidth;
    const h = slot.clientHeight;
    if (!w || !h) return;
    const scale = Math.min(w / CANVAS_W, h / CANVAS_H);
    const x = (w - CANVAS_W * scale) / 2;
    const y = (h - CANVAS_H * scale) / 2;
